#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the argument as a decimal integer */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input: no digits or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Out‑of‑range check (the original program limits to 1 000 000 000) */
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Numbers smaller than 2 have no prime factors */
    if (n < 2) {
        puts("NONE");
        return 0;
    }

    /* Prime‑factorisation */
    int first = 1;               /* flag to control spacing between factors */

    for (long d = 2; d * d <= n; ++d) {
        if (n % d == 0) {
            int exp = 0;
            while (n % d == 0) {
                n /= d;
                ++exp;
            }
            if (!first) putchar(' ');
            printf("%ld^%d", d, exp);
            first = 0;
        }
    }

    /* If a prime factor larger than sqrt(original) remains, it appears with exponent 1 */
    if (n > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", n);
    }

    putchar('\n');
    return 0;
}
